# ─── Added: missing Patch / Rectangle / Circle / Polygon methods ────


def _attach_patch_methods(cls):
    def contains(self, mouseevent):
        try:
            x, y = mouseevent.xdata, mouseevent.ydata
            if x is None or y is None:
                return False, {}
            return self.contains_point((x, y)), {}
        except Exception:
            return False, {}

    def contains_point(self, point, radius=None):
        """Real hit-test dispatching on the patch's concrete subclass.
        Uses analytic equations for circles/ellipses/wedges/annuli and
        ray-casting for polygons/rectangles."""
        x, y = float(point[0]), float(point[1])
        if isinstance(self, Rectangle):
            rx, ry = self.xy
            return (rx <= x <= rx + self.width and
                    ry <= y <= ry + self.height)
        if isinstance(self, Circle):
            cx, cy = self.center
            return (x - cx) ** 2 + (y - cy) ** 2 <= self.radius ** 2
        if isinstance(self, Annulus):
            cx, cy = self.center
            d2 = (x - cx) ** 2 + (y - cy) ** 2
            return self.r_inner ** 2 <= d2 <= self.r_outer ** 2
        if isinstance(self, Wedge):
            import math
            cx, cy = self.center
            d = ((x - cx) ** 2 + (y - cy) ** 2) ** 0.5
            if d > self.r:
                return False
            ang = math.degrees(math.atan2(y - cy, x - cx)) % 360
            t1 = self.theta1 % 360; t2 = self.theta2 % 360
            if t1 <= t2: return t1 <= ang <= t2
            return ang >= t1 or ang <= t2
        if isinstance(self, Ellipse):
            import math
            cx, cy = self.center
            theta = math.radians(getattr(self, 'angle', 0.0) or 0.0)
            cos_t, sin_t = math.cos(-theta), math.sin(-theta)
            dx, dy = x - cx, y - cy
            xr = dx * cos_t - dy * sin_t
            yr = dx * sin_t + dy * cos_t
            a, b = self.width / 2, self.height / 2
            if a == 0 or b == 0: return False
            return (xr / a) ** 2 + (yr / b) ** 2 <= 1.0
        if isinstance(self, Polygon):
            verts = self.xy
            n = len(verts)
            if n < 3: return False
            inside = False; j = n - 1
            for i in range(n):
                xi, yi = verts[i]; xj, yj = verts[j]
                if (yi > y) != (yj > y):
                    x_cross = xi + (y - yi) * (xj - xi) / (yj - yi + 1e-30)
                    if x < x_cross: inside = not inside
                j = i
            return inside
        path = self.get_path() if hasattr(self, 'get_path') else None
        if path is not None and hasattr(path, 'contains_point'):
            return path.contains_point(point)
        return False

    def contains_points(self, points, radius=None):
        import numpy as _np
        return _np.array([self.contains_point(p, radius) for p in points])
    def draw(self, renderer): pass
    def fill(self):                        return getattr(self, '_fill', True)
    def get_fill(self):                    return getattr(self, '_fill', True)
    def set_fill(self, b):                 self._fill = bool(b)
    def get_antialiased(self):             return getattr(self, '_aa', True)
    def set_antialiased(self, b):          self._aa = bool(b)
    def get_capstyle(self):                return getattr(self, '_capstyle', 'butt')
    def set_capstyle(self, s):             self._capstyle = s
    def get_joinstyle(self):               return getattr(self, '_joinstyle', 'miter')
    def set_joinstyle(self, s):            self._joinstyle = s
    def get_linestyle(self):               return getattr(self, '_linestyle', '-')
    def set_linestyle(self, s):            self._linestyle = s
    def get_linewidth(self):               return self._linewidth
    def set_linewidth(self, w):            self._linewidth = float(w)
    def get_hatch(self):                   return getattr(self, '_hatch', None)
    def set_hatch(self, hatch):            self._hatch = hatch
    def get_path(self):
        from matplotlib.path import Path
        return Path.unit_rectangle()
    def get_patch_transform(self):         return None
    def get_data_transform(self):          return None
    def get_transform(self):               return None
    def get_verts(self):
        # Default: empty.
        return []
    def get_extents(self):
        return (0.0, 0.0, 1.0, 1.0)
    def get_window_extent(self, renderer=None): return None
    def set_url(self, url):                self._url = url
    def get_url(self):                     return getattr(self, '_url', None)
    def set_zorder(self, z):               self._zorder = z
    def get_zorder(self):                  return getattr(self, '_zorder', 1)
    def update_from(self, other):
        for attr in ('facecolor', 'edgecolor', 'linewidth', 'alpha'):
            getter = getattr(other, f'get_{attr}', None)
            setter = getattr(self, f'set_{attr}', None)
            if getter and setter:
                try: setter(getter())
                except Exception: pass
    def set_color(self, c):
        self._facecolor = c; self._edgecolor = c
    def set_fc(self, c): self._facecolor = c
    def set_ec(self, c): self._edgecolor = c
    def get_fc(self):    return self._facecolor
    def get_ec(self):    return self._edgecolor

    _l = locals()
    for n in ('contains', 'contains_point', 'contains_points', 'draw',
              'fill', 'get_fill', 'set_fill', 'get_antialiased',
              'set_antialiased', 'get_capstyle', 'set_capstyle',
              'get_joinstyle', 'set_joinstyle', 'get_linestyle',
              'set_linestyle', 'get_linewidth', 'set_linewidth',
              'get_hatch', 'set_hatch', 'get_path', 'get_patch_transform',
              'get_data_transform', 'get_transform',
              'get_verts', 'get_extents', 'get_window_extent',
              'set_url', 'get_url', 'set_zorder', 'get_zorder',
              'update_from', 'set_color', 'set_fc', 'set_ec',
              'get_fc', 'get_ec'):
        if n in _l:
            setattr(cls, n, _l[n])


_attach_patch_methods(Patch)


# Rectangle-specific additions
def _rect_get_x(self):     return self.xy[0]
def _rect_get_y(self):     return self.xy[1]
def _rect_set_x(self, x):  self.xy = (x, self.xy[1])
def _rect_set_y(self, y):  self.xy = (self.xy[0], y)
def _rect_get_angle(self): return getattr(self, 'angle', 0.0)
def _rect_set_angle(self, a): self.angle = float(a)
def _rect_get_bbox(self):
    """Return the bounding box as a real :class:`Bbox` (mirrors
    upstream). Earlier shim returned a numpy array which broke callers
    that did ``rect.get_bbox().x1``."""
    from matplotlib.transforms import Bbox
    # Use get_corners so rotated rectangles report the correct AABB.
    corners = self.get_corners()
    xs = [p[0] for p in corners]
    ys = [p[1] for p in corners]
    return Bbox.from_extents(min(xs), min(ys), max(xs), max(ys))
def _rect_get_center(self):
    return (self.xy[0] + self.width / 2, self.xy[1] + self.height / 2)
def _rect_get_corners(self):
    x, y = self.xy; w, h = self.width, self.height
    return [(x, y), (x + w, y), (x + w, y + h), (x, y + h)]
def _rect_get_patch_transform(self): return None
def _rect_get_path(self):
    from matplotlib.path import Path
    return Path.unit_rectangle()
def _rect_set_bounds(self, *args):
    if len(args) == 1: x, y, w, h = args[0]
    else: x, y, w, h = args
    self.xy = (x, y); self.width = w; self.height = h
def _rect_rotation_point(self):       return 'xy'
def _rect_xy(self):                   return self.xy
Rectangle.get_x          = _rect_get_x
