Rectangle.get_bbox       = _rect_get_bbox
Rectangle.get_center     = _rect_get_center
Rectangle.get_corners    = _rect_get_corners
Rectangle.get_patch_transform = _rect_get_patch_transform
Rectangle.get_path       = _rect_get_path
Rectangle.set_bounds     = _rect_set_bounds
