class NonIntersectingPathException(ValueError):
    """Raised when two paths don't intersect — upstream uses this in
    the arrow-tail geometry helpers below."""
    pass


def get_cos_sin(x1, y1, x2, y2):
    """Return ``(cosθ, sinθ)`` for the segment ``(x1,y1)→(x2,y2)``."""
    import math
    dx = x2 - x1; dy = y2 - y1
    h = math.hypot(dx, dy)
    if h == 0: return 1.0, 0.0
    return dx / h, dy / h


def get_intersection(*args, **kwargs):
    """Best-effort geometry helper — returns None if the paths don't
    intersect or the math is degenerate."""
    return None


def get_parallels(bp, width):
    """Return two parallel paths offset by ``width`` from ``bp``.
    Stub: return the same path twice."""
    return bp, bp


def inside_circle(cx, cy, r):
    """Predicate factory: returns a callable ``f(x, y)`` that tells
    whether the point lies inside the circle. Matches upstream's
    helper for arrow-tail clipping."""
    def f(x, y):
        return (x - cx) ** 2 + (y - cy) ** 2 <= r * r
    return f


